// 处理所有询问，返回每次询问的结果
vector<vector<int>> solve(int n, const vector<int>& arr, const vector<vector<int>>& queries) {
    // pre[i][d] 表示前 i 个数中数字 d 出现的次数
    vector<vector<int>> pre(n + 1, vector<int>(10, 0));

    for (int i = 1; i <= n; i++) {
        // 先继承前一个位置的统计结果
        for (int d = 0; d < 10; d++) {
            pre[i][d] = pre[i - 1][d];
        }
        // 当前数字出现次数加一
        pre[i][arr[i - 1]]++;
    }

    // 预处理个位映射
    int trans[10][10];
    for (int k = 0; k < 10; k++) {
        for (int d = 0; d < 10; d++) {
            trans[k][d] = (d * k) % 10;
        }
    }

    vector<vector<int>> res;

    for (const auto& query : queries) {
        int l = query[0];
        int r = query[1];
        int k = query[2] % 10;

        vector<int> ans(10, 0);

        // 统计区间内原始数字，再映射到结果中
        for (int d = 0; d < 10; d++) {
            int cnt = pre[r][d] - pre[l - 1][d];
            ans[trans[k][d]] += cnt;
        }

        res.push_back(ans);
    }

    return res;
}

int main() {
    int n;
    cin >> n;

    vector<int> arr(n);
    for (int i = 0; i < n; i++) {
        cin >> arr[i];
    }

    int q;
    cin >> q;

    vector<vector<int>> queries(q, vector<int>(3));
    for (int i = 0; i < q; i++) {
        cin >> queries[i][0] >> queries[i][1] >> queries[i][2];
    }

    vector<vector<int>> res = solve(n, arr, queries);

    for (const auto& row : res) {
        for (int i = 0; i < 10; i++) {
            if (i > 0) cout << " ";
            cout << row[i];
        }
        cout << "\n";
    }

    return 0;
}
